"""Candidate questions generated by an LLM, for human review.

Three kinds of candidates:
- single:  one passage -> one question answered by a quote from it;
- linked:  a passage that cites another article of the same law -> a question needing both;
- unanswerable: plausible questions on the corpus topics that these laws do not answer.

Every quote is checked against the corpus and candidates whose quote cannot be found are
dropped (and counted: it measures how often the generator misquotes). Candidates are not
filtered by how hard they are for our retrievers, which would bias the set against the
systems under evaluation. The lexical overlap between question and evidence is recorded,
because generated questions tend to reuse the law's wording, which favours BM25.
"""

from __future__ import annotations

import random
import re
from collections import Counter
from dataclasses import dataclass, field

from rag_ablation_bench.llm import LLM, QuotaExhausted
from rag_ablation_bench.retrieval.text import tokenize
from rag_ablation_bench.schema import Chunk, Document, Section

SYSTEM = (
    "Eres un jurista que prepara un conjunto de evaluación para un buscador de legislación "
    "española. Escribes preguntas realistas de ciudadanos y localizas la cita exacta que las "
    "responde. Responde solo con JSON."
)

SINGLE = """Fragmento de la norma "{law}" ({title}):
<<<
{text}
>>>

Escribe UNA pregunta que haría un ciudadano o un profesional no jurista y que este fragmento responda.
Reglas:
- Pregunta en lenguaje corriente; evita copiar las palabras del texto legal y no cites el número de artículo ni el nombre de la ley.
- Prefiere preguntas sobre plazos, cuantías, requisitos, derechos u obligaciones concretas.
- "quote": copia LITERAL y contigua del fragmento (máximo dos frases) que contiene la respuesta. Copia carácter a carácter.
- "answer": respuesta breve y completa.
- "type": "numeric" si la respuesta es una cifra o porcentaje, si no "lookup".
- Si el fragmento no permite una buena pregunta (solo modifica otras leyes, es una remisión vacía...), devuelve {{"skip": true}}.

Devuelve {{"question": "...", "answer": "...", "quote": "...", "type": "lookup|numeric"}}"""

LINKED = """Dos fragmentos de la norma "{law}". El primero remite al segundo.

[A] {title_a}
<<<
{text_a}
>>>

[B] {title_b}
<<<
{text_b}
>>>

Escribe UNA pregunta realista de un ciudadano cuya respuesta completa necesite información de ambos fragmentos.
Reglas:
- Lenguaje corriente, sin números de artículo ni nombre de la ley.
- "quote_a" y "quote_b": copias LITERALES y contiguas (máximo dos frases cada una) de A y de B con la información necesaria.
- Si no hay una pregunta natural que necesite ambos, devuelve {{"skip": true}}.

Devuelve {{"question": "...", "answer": "...", "quote_a": "...", "quote_b": "..."}}"""

UNANSWERABLE = """El corpus contiene solo estas normas españolas: {laws}.

Escribe {n} preguntas realistas de ciudadanos sobre los mismos temas (trabajo, alquiler, consumo, trámites administrativos, IRPF, protección de datos) que NO puedan responderse con el texto de esas normas: por ejemplo, cifras que fija cada año otra norma, materias reguladas en otras leyes o reglamentos, o casos que dependen de un convenio colectivo concreto. Deben parecer respondibles.

Para cada una, "reason": por qué estas normas no la responden.
Devuelve {{"questions": [{{"question": "...", "reason": "..."}}]}}"""

ARTICLE_REF = re.compile(r"\bart[íi]culos?\s+(\d+(?:\s+(?:bis|ter|quater))?)\b", re.IGNORECASE)


@dataclass
class GenerationStats:
    requested: Counter = field(default_factory=Counter)
    skipped: Counter = field(default_factory=Counter)
    misquoted: Counter = field(default_factory=Counter)
    failed: Counter = field(default_factory=Counter)
    kept: Counter = field(default_factory=Counter)
    stopped: str | None = None  # why generation ended early (provider quota), if it did


def find_quote(section: Section, quote: str) -> str | None:
    """The quote as it appears in the section: exact, or after normalising whitespace and
    typographic quotes (models often change these). None if not found."""
    quote = quote.strip()
    if not quote:
        return None
    if quote in section.text:
        return quote
    words = quote.replace("“", '"').replace("”", '"').replace("’", "'").strip(" .…").split()
    if not words:
        return None
    # Whitespace-tolerant match, returning the text exactly as it is in the section.
    m = re.search(r"\s+".join(re.escape(w) for w in words), section.text)
    return m.group(0) if m else None


def lexical_overlap(question: str, evidence: str) -> float:
    """Share of the question's content words (stemmed) that appear in the evidence."""
    q = set(tokenize(question))
    return len(q & set(tokenize(evidence))) / len(q) if q else 0.0


def _ref(doc: Document, section: Section) -> str:
    return f"{doc.short_title}#{section.id.split('#', 1)[1]}"


def _eligible(
    chunks: list[Chunk], sections: dict[str, Section], used: set[str], min_words: int
) -> list[Chunk]:
    out = []
    for c in chunks:
        sec = sections[c.section_ids[0]]
        if (
            sec.kind in ("article", "provision", "annex")
            and not sec.metadata.get("repealed")
            and sec.id not in used
            and len(c.text.split()) >= min_words
        ):
            out.append(c)
    return out


def generate(
    docs: list[Document],
    chunks: list[Chunk],
    llm: LLM,
    **kwargs,
) -> tuple[list[dict], GenerationStats]:
    """Review candidates as dicts in the evaluation-set YAML format. If the provider's
    quota runs out, the candidates made so far are returned and `stats.stopped` says why."""
    candidates: list[dict] = []
    stats = GenerationStats()
    try:
        _generate(docs, chunks, llm, candidates, stats, **kwargs)
    except QuotaExhausted as exc:
        stats.stopped = str(exc)
    return candidates, stats


def _generate(
    docs: list[Document],
    chunks: list[Chunk],
    llm: LLM,
    candidates: list[dict],
    stats: GenerationStats,
    *,
    n_single: int,
    n_linked: int,
    n_unanswerable: int,
    used_sections: set[str],
    seed: int = 0,
    min_words: int = 40,
) -> None:
    rng = random.Random(seed)
    by_id = {d.id: d for d in docs}
    sections = {s.id: s for d in docs for s in d.sections}
    pool = _eligible(chunks, sections, used_sections, min_words)

    # Single-passage questions, spread evenly over the laws.
    per_doc: dict[str, list[Chunk]] = {}
    for c in pool:
        per_doc.setdefault(c.doc_id, []).append(c)
    for lst in per_doc.values():
        rng.shuffle(lst)
    order = [c for group in zip(*per_doc.values(), strict=False) for c in group]
    for c in order[:n_single]:
        sec, doc = sections[c.section_ids[0]], by_id[c.doc_id]
        stats.requested["single"] += 1
        prompt = SINGLE.format(law=doc.title, title=sec.title, text=c.text)
        try:
            data, _ = llm.ask_json(SYSTEM, prompt)
        except ValueError:
            stats.failed["single"] += 1
            continue
        if data.get("skip"):
            stats.skipped["single"] += 1
            continue
        quote = find_quote(sec, str(data.get("quote", "")))
        if quote is None or not data.get("question"):
            stats.misquoted["single"] += 1
            continue
        stats.kept["single"] += 1
        candidates.append(
            {
                "question": data["question"],
                "answer": data.get("answer", ""),
                "type": data.get("type") if data.get("type") in ("lookup", "numeric") else "lookup",
                "evidence": [{"ref": _ref(doc, sec), "quote": quote}],
                "lexical_overlap": round(lexical_overlap(data["question"], quote), 3),
            }
        )

    # Linked questions from explicit cross-references inside the same law.
    titles = {
        (s.doc_id, m.group(1).lower()): s
        for s in sections.values()
        if s.kind == "article" and (m := re.match(r"Artículo (\d+(?: bis| ter)?)\.", s.title))
    }
    pairs = []
    for c in pool:
        sec = sections[c.section_ids[0]]
        for m in ARTICLE_REF.finditer(c.text):
            target = titles.get((c.doc_id, m.group(1).lower()))
            if target is not None and target.id != sec.id and not target.metadata.get("repealed"):
                pairs.append((c, target))
    rng.shuffle(pairs)
    seen_pairs = set()
    for c, target in pairs:
        if stats.requested["linked"] >= n_linked:
            break
        sec, doc = sections[c.section_ids[0]], by_id[c.doc_id]
        if (sec.id, target.id) in seen_pairs:
            continue
        seen_pairs.add((sec.id, target.id))
        stats.requested["linked"] += 1
        prompt = LINKED.format(
            law=doc.title,
            title_a=sec.title,
            text_a=c.text,
            title_b=target.title,
            text_b=" ".join(target.text.split()[:600]),
        )
        try:
            data, _ = llm.ask_json(SYSTEM, prompt)
        except ValueError:
            stats.failed["linked"] += 1
            continue
        if data.get("skip"):
            stats.skipped["linked"] += 1
            continue
        qa = find_quote(sec, str(data.get("quote_a", "")))
        qb = find_quote(target, str(data.get("quote_b", "")))
        if qa is None or qb is None or not data.get("question"):
            stats.misquoted["linked"] += 1
            continue
        stats.kept["linked"] += 1
        candidates.append(
            {
                "question": data["question"],
                "answer": data.get("answer", ""),
                "type": "multi_evidence",
                "evidence": [
                    {"ref": _ref(doc, sec), "quote": qa},
                    {"ref": _ref(doc, target), "quote": qb},
                ],
                "lexical_overlap": round(lexical_overlap(data["question"], qa + " " + qb), 3),
            }
        )

    # Unanswerable questions: the reviewer must confirm the corpus really lacks the answer.
    if n_unanswerable:
        stats.requested["unanswerable"] += n_unanswerable
        laws = "; ".join(d.title for d in docs)
        try:
            data, _ = llm.ask_json(SYSTEM, UNANSWERABLE.format(laws=laws, n=n_unanswerable))
            items = data.get("questions", [])
        except ValueError:
            items = []
            stats.failed["unanswerable"] += 1
        for item in items[:n_unanswerable]:
            if not item.get("question"):
                continue
            stats.kept["unanswerable"] += 1
            candidates.append(
                {
                    "question": item["question"],
                    "answer": "UNANSWERABLE",
                    "type": "unanswerable",
                    "notes": item.get("reason", ""),
                }
            )
